 static float Smooth(float a,float b,float x)=>Mathf.SmoothStep(0,1,Mathf.InverseLerp(a,b,x));
 public static float RoadZ(float x)=>-28-.035f*(-51-x)+Mathf.Sin((x+192)*.006f)*6*Smooth(0,100,-x-192);
 static float FarHeight(float x,float z){float n=Mathf.PerlinNoise(x*.003f+17,z*.003f+39);float waves=Mathf.Sin(x*.007f+z*.003f)*6+Mathf.Cos(z*.011f-x*.004f)*5;float hills=3+waves+(n-.35f)*24;float side=Smooth(35,170,Mathf.Abs(z-RoadZ(x)));float road=-.9f+Mathf.Sin((x+192)*.009f)*1.6f+Smooth(180,510,-x-192)*4;return Mathf.Lerp(road,hills,side);}
