 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F required");var root=GameObject.Find("1F_AbandonedFactory");if(root.transform.Find("WildernessEnding"))throw new Exception("Already exists");near=GameObject.Find("AE_OvergrownFactoryTerrain").GetComponent<Terrain>();var parent=Group("WildernessEnding",root.transform,Vector3.zero).transform;
 var td=new TerrainData{name="FW_WildernessTerrain",heightmapResolution=2049,alphamapResolution=1024,baseMapResolution=1024,size=new Vector3(1536,100,1280)};AssetDatabase.CreateAsset(td,E+"FW_WildernessTerrain.asset");int n=2049;var heights=new float[n,n];for(int z=0;z<n;z++)for(int x=0;x<n;x++)heights[z,x]=(Height(-768+x*.75f,-640+z*.625f)+6)/100;td.SetHeights(0,0,heights);var holes=new bool[n-1,n-1];for(int z=0;z<n-1;z++)for(int x=0;x<n-1;x++)holes[z,x]=!(x>=768&&x<1280&&z>=768&&z<1280);td.SetHoles(0,0,holes);
