 var alpha=new float[1024,1024,3];for(int z=0;z<1024;z++)for(int x=0;x<1024;x++){float wx=-768+x*1536f/1023,wz=-640+z*1280f/1023;float road=1-Smooth(2.5f,8,Mathf.Abs(wz-RoadZ(wx)));float gravel=.12f+.65f*road;float dry=.22f+.25f*Mathf.PerlinNoise(wx*.025f+6,wz*.025f+9);alpha[z,x,0]=(1-gravel)*(1-dry);alpha[z,x,1]=gravel;alpha[z,x,2]=(1-gravel)*dry;}td.SetAlphamaps(0,0,alpha);
