 foreach(var q in new[]{new {name="EndingWalkStart",x=-82f},new{name="EndingWalkMid",x=-285f},new{name="FreedomVista",x=-590f}}){float z=RoadZ(q.x);var g=Group(q.name,parent,new Vector3(q.x,Height(q.x,z),z));g.transform.rotation=Quaternion.Euler(0,270,0);}
