 if(RenderSettings.sun){RenderSettings.sun.transform.rotation=Quaternion.Euler(22,85,0);RenderSettings.sun.color=new Color(1,.88f,.69f);RenderSettings.sun.intensity=1.3f;}
 RenderSettings.ambientSkyColor=new Color(.54f,.61f,.69f);RenderSettings.ambientEquatorColor=new Color(.43f,.40f,.33f);RenderSettings.ambientGroundColor=new Color(.23f,.20f,.16f);RenderSettings.fog=true;RenderSettings.fogMode=FogMode.Linear;RenderSettings.fogStartDistance=180;RenderSettings.fogEndDistance=1350;RenderSettings.fogColor=new Color(.67f,.68f,.65f);
 foreach(var camera in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true))){camera.farClipPlane=2200;var sb=camera.GetComponent<Skybox>();if(sb)sb.material=sky;Record(camera.gameObject);}
